//! Percent-encoding and percent-decoding.
//!
//! Both routines are byte oriented: multi-byte UTF-8 sequences are encoded one
//! octet at a time, and decoding can legitimately produce byte strings that are
//! not valid UTF-8 (`%ff` decodes to the single octet 0xff). That is why the
//! public API speaks `[u8]`/`Vec<u8>` rather than `str`/`String`.

/// Unreserved characters per RFC 3986: ALPHA / DIGIT / "-" / "." / "_" / "~".
/// Every other octet is escaped.
fn is_unreserved(b: u8) -> bool {
    b.is_ascii_alphanumeric() || matches!(b, b'-' | b'_' | b'.' | b'~')
}

/// Value of a single hex digit, or `None` if `b` is not a hex digit.
/// Both upper and lower case are accepted.
fn hex_value(b: u8) -> Option<u8> {
    match b {
        b'0'..=b'9' => Some(b - b'0'),
        b'a'..=b'f' => Some(b - b'a' + 10),
        b'A'..=b'F' => Some(b - b'A' + 10),
        _ => None,
    }
}

/// Percent-encode `input`, escaping everything outside the unreserved set.
/// Escapes use lower case hex digits (`%2f`, not `%2F`).
pub fn url_encode(input: &[u8]) -> Vec<u8> {
    const HEX: &[u8; 16] = b"0123456789abcdef";

    let mut out = Vec::with_capacity(input.len());
    for &b in input {
        if is_unreserved(b) {
            out.push(b);
        } else {
            out.push(b'%');
            out.push(HEX[(b >> 4) as usize]);
            out.push(HEX[(b & 0x0f) as usize]);
        }
    }
    out
}

/// Percent-decode `input`, additionally translating `+` to a space.
///
/// A `%` that is not followed by two hex digits is not an error: it is copied
/// through verbatim and scanning resumes at the next byte. So `"%zz"` decodes to
/// `"%zz"`, `"%4"` to `"%4"`, and `"%%41"` to `"%A"`.
pub fn url_decode(input: &[u8]) -> Vec<u8> {
    let mut out = Vec::with_capacity(input.len());
    let mut i = 0;

    while i < input.len() {
        match input[i] {
            b'+' => {
                out.push(b' ');
                i += 1;
            }
            b'%' if i + 2 < input.len() => {
                match (hex_value(input[i + 1]), hex_value(input[i + 2])) {
                    (Some(hi), Some(lo)) => {
                        out.push((hi << 4) | lo);
                        i += 3;
                    }
                    // Malformed escape: emit the '%' and move on.
                    _ => {
                        out.push(b'%');
                        i += 1;
                    }
                }
            }
            b => {
                out.push(b);
                i += 1;
            }
        }
    }
    out
}

