//! A minimal URL splitter covering the generic syntax of RFC 3986:
//! `scheme://userinfo@host:port/path?query#fragment`.

/// A parsed URL. Components are stored already separated; absent components are
/// empty strings rather than `Option`s, mirroring the accessors' return type.
pub struct URL {
    scheme: String,
    userinfo: String,
    host: String,
    port: String,
    path: String,
    query: String,
    fragment: String,
}

impl URL {
    /// Split `input` into its components. Parsing never fails; anything that
    /// does not match the generic syntax simply lands in `path`.
    pub fn new(input: &str) -> URL {
        let mut rest = input;

        // Trailing components first, so that a '?' or '#' inside the fragment
        // cannot be mistaken for a delimiter of an earlier component.
        let fragment = match rest.find('#') {
            Some(i) => {
                let f = &rest[i + 1..];
                rest = &rest[..i];
                f
            }
            None => "",
        };

        let query = match rest.find('?') {
            Some(i) => {
                let q = &rest[i + 1..];
                rest = &rest[..i];
                q
            }
            None => "",
        };

        // scheme:// -- only a hierarchical URL has an authority component.
        let mut scheme = "";
        if let Some(i) = rest.find("://") {
            scheme = &rest[..i];
            rest = &rest[i + 3..];
        }

        // The authority runs up to the first '/', which begins the path.
        let (authority, path) = match rest.find('/') {
            Some(i) => (&rest[..i], &rest[i..]),
            None => (rest, ""),
        };

        // userinfo@ -- use the last '@' so that one inside the userinfo itself
        // does not truncate the host.
        let (userinfo, hostport) = match authority.rfind('@') {
            Some(i) => (&authority[..i], &authority[i + 1..]),
            None => ("", authority),
        };

        // host:port -- a bracketed IPv6 literal contains colons of its own, so
        // only look for the port separator after the closing bracket.
        let colon = match hostport.rfind(']') {
            Some(b) => hostport[b..].find(':').map(|i| b + i),
            None => hostport.rfind(':'),
        };
        let (host, port) = match colon {
            Some(i) => (&hostport[..i], &hostport[i + 1..]),
            None => (hostport, ""),
        };

        URL {
            // The scheme is case insensitive; normalise it.
            scheme: scheme.to_ascii_lowercase(),
            userinfo: userinfo.to_string(),
            host: host.to_string(),
            port: port.to_string(),
            path: path.to_string(),
            query: query.to_string(),
            fragment: fragment.to_string(),
        }
    }

    pub fn scheme(&self) -> &str {
        &self.scheme
    }

    pub fn userinfo(&self) -> &str {
        &self.userinfo
    }

    pub fn host(&self) -> &str {
        &self.host
    }

    pub fn port(&self) -> &str {
        &self.port
    }

    pub fn path(&self) -> &str {
        &self.path
    }

    pub fn query(&self) -> &str {
        &self.query
    }

    pub fn fragment(&self) -> &str {
        &self.fragment
    }

    /// The query split into `key`/`value` pairs on `&` and `=`, in order.
    ///
    /// Keys and values are percent-decoded, so a pair may hold arbitrary
    /// bytes (`%ff` decodes to the octet 0xff) and is therefore returned as
    /// `Vec<u8>` rather than `String`. Splitting happens before decoding, so an
    /// escaped `%26` inside a value is not mistaken for a separator.
    /// A segment with no `=` yields an empty value; empty segments are skipped.
    pub fn query_params(&self) -> Vec<(Vec<u8>, Vec<u8>)> {
        let mut params = Vec::new();

        for segment in self.query.split('&') {
            if segment.is_empty() {
                continue;
            }
            let (key, value) = match segment.find('=') {
                Some(i) => (&segment[..i], &segment[i + 1..]),
                None => (segment, ""),
            };
            params.push((
                url_decode(key.as_bytes()),
                url_decode(value.as_bytes()),
            ));
        }
        params
    }
}

