use std::io::{self, Write};

// Spelled out with #[path] so this file compiles both as the Cargo bin target
// and standalone via `rustc test17.rs`.
#[path = "src/url_parser/mod.rs"]
mod url_parser;

use url_parser::{url_decode, url_encode, URL};

fn main() {
    let args: Vec<String> = std::env::args().collect();
    if args.len() < 2 {
        std::process::exit(1);
    }
    let str = args[1].as_bytes();

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());

    // Decoded output can be arbitrary bytes, not just UTF-8, so write bytes.
    let mut line = |bytes: &[u8]| {
        out.write_all(bytes).unwrap();
        out.write_all(b"\n").unwrap();
    };

    let encoded = url_encode(str);
    line(&encoded);
    line(&url_decode(str));

    let mut raw = Vec::from(&b"http://example.com/test?q="[..]);
    raw.extend_from_slice(&encoded);
    // `encoded` is percent-escaped, hence pure ASCII, so this cannot fail.
    let parser = URL::new(&String::from_utf8(raw).unwrap());

    line(parser.scheme().as_bytes());
    line(parser.host().as_bytes());
    line(parser.path().as_bytes());
    line(parser.query().as_bytes());

    for (key, value) in parser.query_params() {
        line(&url_decode(key.as_bytes()));
        line(&url_decode(value.as_bytes()));
    }
}
